437→func assertKiroHookCommand(t *testing.T, entries []kiroHookEntry, expectedCommand string) {
438→	t.Helper()
439→	if len(entries) == 0 {
440→		t.Errorf("expected hook entry with command %q, got empty slice", expectedCommand)
441→		return
442→	}
443→	found := false
444→	for _, entry := range entries {
445→		if entry.Command == expectedCommand {
446→			found = true
447→			break
448→		}
449→	}
450→	if !found {
451→		commands := make([]string, 0, len(entries))
452→		for _, entry := range entries {
453→			commands = append(commands, entry.Command)
454→		}
455→		t.Errorf("expected hook command %q, got %v", expectedCommand, commands)
456→	}
457→}
