 91→// --- Session Management ---
 92→
 93→// GetSessionID extracts the session ID from hook input.
 94→func (k *KiroAgent) GetSessionID(input *agent.HookInput) string {
 95→	return input.SessionID
 96→}
 97→
 98→// GetSessionDir returns the directory where Kiro stores session data.
 99→// For Kiro, sessions are in SQLite, but we cache transcripts to .entire/tmp/.
100→func (k *KiroAgent) GetSessionDir(repoPath string) (string, error) {
101→	return filepath.Join(repoPath, ".entire", "tmp"), nil
102→}
