104→// ResolveSessionFile returns the path to the cached transcript file.
105→func (k *KiroAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
106→	return filepath.Join(sessionDir, agentSessionID+".json")
107→}
108→
109→// ReadSession reads session data from the cached transcript.
110→func (k *KiroAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
111→	if input.SessionRef == "" {
112→		return nil, errors.New("session reference (transcript path) is required")
113→	}
114→
115→	data, err := os.ReadFile(input.SessionRef)
116→	if err != nil {
117→		return nil, fmt.Errorf("failed to read transcript: %w", err)
118→	}
119→
120→	return &agent.AgentSession{
121→		SessionID:  input.SessionID,
122→		AgentName:  k.Name(),
123→		SessionRef: input.SessionRef,
124→		StartTime:  time.Now(),
125→		NativeData: data,
126→	}, nil
127→}
128→
129→// WriteSession writes session data for resumption.
130→func (k *KiroAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
131→	if session == nil {
132→		return errors.New("session is nil")
133→	}
134→	if session.AgentName != "" && session.AgentName != k.Name() {
135→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, k.Name())
136→	}
137→	if session.SessionRef == "" {
138→		return errors.New("session reference (transcript path) is required")
139→	}
140→	if len(session.NativeData) == 0 {
141→		return errors.New("session has no native data to write")
142→	}
143→
144→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
145→		return fmt.Errorf("failed to create session dir: %w", err)
146→	}
147→
148→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
149→		return fmt.Errorf("failed to write transcript: %w", err)
150→	}
151→	return nil
152→}
